def estimate(points, x):
    """Piecewise linear interpolation.

    * ``points`` must be a non‑empty list of ``(x, y)`` sorted by ``x``.
    * If there is only one point, its ``y`` is returned for any ``x``.
    * For ``x`` outside the support, the nearest endpoint ``y`` is returned (clamping).
    * Otherwise, linear interpolation between the surrounding points is performed.
    """
    if not points:
        raise ValueError("no points for interpolation")
    if len(points) == 1:
        return points[0][1]
    # Clamp to endpoints
    if x <= points[0][0]:
        return points[0][1]
    if x >= points[-1][0]:
        return points[-1][1]
    # Find interval
    for i in range(1, len(points)):
        left, right = points[i - 1], points[i]
        if x <= right[0]:
            # Linear interpolation preserving sign of slope
            x0, y0 = left
            x1, y1 = right
            return y0 + (y1 - y0) * (x - x0) / (x1 - x0)
    # Should never reach here because of clamping
    raise RuntimeError("interpolation failed")

