def prepare(points):
    """Validate and sort sample points.

    * ``points`` is an iterable of ``(x, y)`` pairs.
    * Duplicate ``x`` values raise ``ValueError``.
    * An empty ``points`` iterable raises ``ValueError``.
    * Returns a list of ``(x, y)`` sorted by ``x``.
    """
    seen = {}
    for x, y in points:
        if x in seen:
            raise ValueError("duplicate coordinate")
        seen[x] = y
    if not seen:
        raise ValueError("empty samples")
    # Return items sorted by x coordinate
    return sorted(seen.items(), key=lambda item: item[0])

